#include <stdio.h>

int is_perfect(int n) {
    int sum = 0;
    for (int d = 1; d < n; d++) {
        if (n % d == 0) {
            sum += d;
        }
    }
    return sum == n;
}

int main() {
    int numbers[] = {6, 12};
    for (int i = 0; i < 2; i++) {
        printf("%d %s\n", numbers[i], is_perfect(numbers[i]) ? "yes" : "no");
    }
    return 0;
}
